-- Extensões necessárias
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Roles de Autenticação do PostgREST
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'authenticator') THEN
    CREATE ROLE authenticator NOINHERIT LOGIN PASSWORD 'pita_secure_authenticator_2026';
  END IF;
END
$$;

GRANT anon TO authenticator;

-- 1. Tabela: categories
CREATE TABLE IF NOT EXISTS categories (
    id SERIAL PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    description TEXT,
    icon TEXT,
    color TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- 2. Tabela: projects
CREATE TABLE IF NOT EXISTS projects (
    id SERIAL PRIMARY KEY,
    category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,
    slug TEXT NOT NULL,
    title TEXT NOT NULL,
    client TEXT,
    year INTEGER DEFAULT 2025,
    services JSONB DEFAULT '[]'::jsonb,
    description TEXT,
    challenge TEXT,
    solution TEXT,
    results TEXT,
    project_url TEXT,
    main_image_url TEXT,
    gallery_urls JSONB DEFAULT '[]'::jsonb,
    allow_image_download BOOLEAN DEFAULT true,
    video_urls JSONB DEFAULT '[]'::jsonb,
    main_image_aspect_ratio TEXT DEFAULT '16:9',
    gallery_aspect_ratio TEXT DEFAULT '4:5',
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- 3. Tabela: reviews
CREATE TABLE IF NOT EXISTS reviews (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT,
    rating INTEGER DEFAULT 5,
    comment TEXT,
    avatar_url TEXT,
    is_approved BOOLEAN DEFAULT true,
    likes INTEGER DEFAULT 0,
    user_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

