-- 7. Tabela: subscriptions
CREATE TABLE IF NOT EXISTS subscriptions (
    id SERIAL PRIMARY KEY,
    plan_name TEXT NOT NULL,
    price_monthly NUMERIC(10,2),
    price_yearly NUMERIC(10,2),
