INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (42, 3, 'sms-facil-plataforma-saas-de-numeros-virtuais', 'SMS Fácil - Plataforma SaaS de Números Virtuais', 'Matheus', 2026, '["React","Tailwind CSS","Supabase","Node.js","Docker","PostgreSQL","subcategoria:desenvolvimento-de-sistemas"]'::jsonb, 'Uma plataforma moderna e automatizada para venda de números temporários (SMS), com processamento de pagamentos Pix em tempo real, painel administrativo completo e arquitetura Docker escalável.', 'Garantir a integridade financeira (saldo) em um sistema de alta concorrência e migrar uma infraestrutura instável e manual para um ambiente de produção profissional e seguro.', 'Desenvolvimento de plataforma SaaS em Next.js 14 e PostgreSQL, utilizando Docker para padronização do ambiente produtivo.
Backend: Implementação de transações atômicas (ACID) para eliminar erros de "gasto duplo" (Race Conditions).
DevOps: Containerização completa da aplicação e criação de rotinas automáticas de backup via Shell Script e Cron.
Finanças: Integração de gateway de pagamento Pix com Webhooks blindados para liberação imediata de saldo.', 'Estabilidade: 100% de uptime registrado após migração para Docker com política de auto-restart.
Segurança: Zero incidentes de inconsistência de saldo reportados.
