INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (41, 3, 'rafael-pita-phothography-site', 'Rafael Pita Phothography', '', 2026, '["React","Tailwind CSS","Supabase","Node.js","SEO Premium","subcategoria:desenvolvimento-de-sistemas"]'::jsonb, 'Criamos uma vitrine digital de alto impacto, focada em transformar visitantes em clientes. Uma experiência visual impecável que reflete a qualidade e o profissionalismo da sua arte.', 'O desafio era garantir carregamento ultrarrápido e navegação intuitiva, mesmo com um extenso portfólio de imagens de alta resolução.', 'Implementamos um design minimalista e customizado, utilizando uma arquitetura de desenvolvimento web otimizada para performance máxima e responsividade mobile.', 'O resultado é um portfólio que fortalece a credibilidade da marca e eleva significativamente a taxa de conversão de agendamentos de fotografia.', 'https://rafaelpitaoficial.com.br/portfolio-fotografia', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Frafael-pita-phothography-site-main-1768330097453-imagem_2026-01-13_154228153.webp?alt=media&token=43f23885-07a4-40c4-8381-e2778ad060a8', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Frafael-pita-phothography-site-gallery-1768330097453-0-imagem_2026-01-13_154322734.webp?alt=media&token=5e8c15c3-d1bb-4442-a23e-1f73f92890f3","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Frafael-pita-phothography-site-gallery-1768330097453-1-imagem_2026-01-13_154343378.webp?alt=media&token=4d06d67b-c28b-4d87-b2b3-a03513d2b963","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portf