INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (35, 3, 'landing-page-cbjjo', 'CBJJO - Landing Page', '', 2024, '["React","Tailwind CSS","Supabase","SEO Premium","Framer Motion","subcategoria:landing-pages"]'::jsonb, 'Desenvolvimento de uma Landing Page estratégica e de alto impacto para a Confederação [Cliente Confidencial]. Uma interface robusta projetada para maximizar a captação e o engajamento dos usuários.', 'O principal desafio era garantir carregamento instantâneo e uma arquitetura limpa, capaz de suportar alto volume de acessos e conversões.', 'Implementamos um desenvolvimento web otimizado (dev web), focando em performance de código limpo e design responsivo de excelência.', 'Entregamos uma plataforma digital profissional que superou as metas iniciais de performance e se estabeleceu como um forte canal de comunicação e captação.', 'https://cbjjo.vercel.app', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-main-1768255593449-imagem_2026-01-12_190013843.webp?alt=media&token=b4889f5e-2dd5-48a2-89fe-094577784eed', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-0-imagem_2026-01-12_190025581.webp?alt=media&token=dd11041b-10ae-4848-aa2b-59d6a7d539d1","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-1-imagem_2026-01-12_190053538.webp?alt=media&token=99bfdf20-fa84-4a55-9e47-606bcdbfca50","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-2-imagem_2026-01-12_190111694.webp?alt=media&token=2fd0cad4-5b5f-4fa3-96d5-3d6df8a1d374","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-3-imagem_2026-01-12_190136170.webp?alt=media&token=f9d41c1a-8420-4d37-8319-446fd200f1f6","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-4-imagem_2026-01-12_190147108.webp?alt=media&token=1bf3966b-4778-40c8-a9e4-46fd60950a03","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-5-imagem_2026-01-12_190437764.webp?alt=media&token=6b8cd5c4-c0ee-4efb-88d4-ae4bda4b948e","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-6-imagem_2026-01-12_190451304.webp?alt=media&token=d884faaa-564f-463b-8e39-c22070225b02","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Flanding-page-cbjjo-gallery-1768255593449-7-imagem_2026-01-12_190624988.webp?alt=media&token=d5df2772-1c9f-498a-96dd-14c80ceb3f58"]'::jsonb, '2026-01-12T22:06:36.214352+00:00', true, '[]'::jsonb, '16:9', '16:9', 27) ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (17, 4, 'power-bi', 'Relatórios em Power BI', 'TP', 2025, '["Power BI","DAX","Power Query","ETL","SQL Server","subcategoria:dashboards-power-bi"]'::jsonb, 'Desenvolvemos uma suíte de dashboards interativos em Power BI para o cliente TP, convertendo dados complexos em inteligência de negócios acionável. Este projeto demonstra nossa expertise em ETL e visualização estratégica de dados.', 'O desafio central era unificar dados dispersos em SQL através de processos ETL robustos, garantindo alta performance e confiabilidade na visualização de relatórios gerenciais.', 'Implementamos uma arquitetura de dados otimizada e um design de dashboard intuitivo, permitindo que a gestão da TP explorasse indicadores-chave com máxima clareza e em tempo real.', 'O resultado direto foi uma redução significativa no tempo de geração de relatórios manuais e um aumento comprovado na precisão das tomadas de decisão estratégicas.', '', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fpower-bi-main-1759369951828-5af628231093089.688279da319e8.webp?alt=media&token=07696295-8112-433b-8b23-fb21020e6869', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fpower-bi-gallery-1759369951828-0-5af628231093089.688279da319e8.webp?alt=media&token=73767fb0-ce64-432f-91f2-a9f2b65cc356","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fpower-bi-gallery-1759369951828-1-507fc0231093089.688279db1a1c34%20(1).webp?alt=media&token=fd2e9e8c-a72f-4a62-93b7-0f3fc2228aba","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.fir