ps://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fpower-bi-gallery-1759369951828-11-fe5568231093089.688279db1a8a6.webp?alt=media&token=716acd3f-c495-4e37-af22-f06ce243dc9a"]'::jsonb, '2025-10-02T01:52:33.155618+00:00', true, '[]'::jsonb, '16:9', '4:5', 39) ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (37, 3, 'moy-seguros-site-e-sorteio', 'Moy Seguros - Site e Sorteio', 'Moises', 2025, '["React","Tailwind CSS","Supabase","Node.js","SEO Premium","subcategoria:landing-pages"]'::jsonb, 'Potencializamos a captação de leads para a Moy Seguros através de uma experiência digital e visualmente impactante. Desenvolvemos o novo website e a campanha de sorteio com foco em alta conversão.', 'O desafio era transformar um serviço tradicional (seguros) em uma plataforma digital envolvente, maximizando a captura de novos leads.', 'Resolvemos criando confiança e clareza imediata na jornada do usuário.', 'O resultado foi uma plataforma de alta qualidade estética, pronta para gerar taxas de conversão elevadas para a campanha de sorteio.', 'https://moy-sorteio-digital.vercel.app', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fmoy-seguros-site-e-sorteio-main-1768256324269-imagem_2026-01-12_191405361.webp?alt=media&token=720d5e68-c1a2-49a2-92db-c55d6f052adb', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fmoy-seguros-site-e-sorteio-gallery-1768256324269-0-imagem_2026-01-12_191410243.webp?alt=media&token=1dd6f3e5-83ba-4b62-ac26-0427e9320671","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fmoy-seguros-site-e-sorteio-gallery-1768256324269-1-imagem_2026-01-12_191420278.webp?alt=media&token=61a7f3d5-0e6b-4254-b7ba-9e38b58c8249","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fmoy-seguros-site-e-sorteio-gallery-1768256324269-2-imagem_2026-01-12_1