INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (3, 1, 'brito-adv', 'Social Media - Brito Adv', 'Brito', 2025, '["Figma","Adobe Photoshop","Illustrator","Imagens em IA","subcategoria:social-media"]'::jsonb, 'O escritório Brito Advocacia pediu artes para feed e stories no Instagram a fim de divulgar uma vaga de estágio.', 'Comunicar a oportunidade de forma clara e profissional, mantendo a identidade visual do escritório e atraindo estudantes de Direito.', 'Criei peças visuais alinhadas à identidade da marca, com layout sóbrio no feed e versão mais dinâmica nos stories para gerar engajamento.', 'A divulgação atraiu candidatos qualificados e reforçou a presença digital da Brito Advocacia.', 'https://google.com.br', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fbrito-adv-main-1758297633394-1.webp?alt=media&token=2b352fc1-d8bb-4d4d-8539-f131e08b8ee7', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fbrito-adv-gallery-1758297633394-0-(Story)%201.webp?alt=media&token=f8f6b9bd-7e8a-468a-9109-121f89958ffc","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fbrito-adv-gallery-1758297633394-1-2%20(Story).webp?alt=media&token=0ffe5f06-0252-4702-93fc-dbdb95d2aca5","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fbrito-adv-gallery-1758297633394-2-feed%201.webp?alt=media&token=a39cd6b6-6bbd-47d1-a58b-fe945ee4991b","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fbrito-adv-gallery-1758297633394-3-feed%202.webp?alt=media&token=d68571ba