INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (38, 3, 'contabilidade-landing-page', 'Contabilidade - Landing Page', 'Walter Muniz', 2025, '["React","Tailwind CSS","Supabase","SEO Premium","Framer Motion","subcategoria:landing-pages"]'::jsonb, 'Criamos uma Landing Page de alta performance para a contabilidade Walter Muniz, focada na credibilidade e na conversão direta. Uma solução digital robusta para atrair e qualificar novos clientes de forma eficiente.', 'O principal desafio era traduzir a complexidade dos serviços de contabilidade em uma interface clara e que inspirasse total confiança.', 'A solução envolveu uma arquitetura de UX clean, utilizando CTAs estratégicos.', 'O resultado é uma ferramenta posiciona o cliente como autoridade e aumenta significativamente a taxa de conversão.', 'https://muniz-tax-hub.vercel.app', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcontabilidade-landing-page-main-1768256670360-imagem_2026-01-12_192245587.webp?alt=media&token=937249db-a681-4a5a-8c99-a63972cdae77', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcontabilidade-landing-page-gallery-1768256670360-0-imagem_2026-01-12_192318572.webp?alt=media&token=8dd69605-c74f-4912-9c87-9f3f581e1723","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcontabilidade-landing-page-gallery-1768256670360-1-imagem_2026-01-12_192327118.webp?alt=media&token=57fcc8de-eecd-41f4-b0bf-7bccb6f6c6b2","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcontabilidade-landing-page-gallery-1768256670360-2-imagem