INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (15, 1, 'nobre-propagando', 'Inobre - Social Media', 'Fernanda', 2025, '["Figma","Adobe Photoshop","Illustrator","Imagens em IA","subcategoria:social-media"]'::jsonb, 'A Nobre Propaganda solicitou a criação de artes em carrossel para feed e novas capas de destaques no Instagram, como parte de uma repaginada em sua identidade visual.', 'Atualizar a presença digital da agência, trazendo modernidade sem perder a essência da marca.', 'Redesenhei os elementos visuais para os carrosséis e destaques, aplicando uma linguagem mais atual e coerente com o reposicionamento da marca.', 'A nova identidade deixou o perfil mais moderno e profissional, fortalecendo a imagem da agência perante seus clientes e seguidores.', '', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fnobre-propagando-main-1759194921711-17.webp?alt=media&token=d8384a4e-9253-4d7c-9544-04e85f62131b', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fnobre-propagando-gallery-1759194921711-0-4.webp?alt=media&token=a3f888d0-538f-4078-bf66-bbb5182e1bac","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fnobre-propagando-gallery-1759194921711-1-6.webp?alt=media&token=61bba1ee-af1a-4bd7-b8db-4369ef41f0a8","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fnobre-propagando-gallery-1759194921711-2-9.webp?alt=media&token=dc409fe4-8488-4da5-b328-a3a6e31def69","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fnobre-propagando-gallery-