INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (4, 1, 'cardapio-la-bella-pasta', 'Cardápio - La Bella Pasta', 'Maria', 2025, '["Figma","Adobe Photoshop","Illustrator","Branding"]'::jsonb, 'O restaurante La Bella Pasta, especializado em comida italiana, solicitou a criação de um cardápio para impressão.', 'Transmitir a identidade italiana da marca em um material funcional, de fácil leitura e adequado para o uso em mesas.', 'Desenvolvi um layout elegante, com tipografia clara e elementos visuais que remetem à culinária italiana, organizando os pratos de forma prática.', 'O cardápio reforçou a identidade visual do restaurante e trouxe mais profissionalismo à experiência dos clientes.', '', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcardapio-la-bella-pasta-main-1758298262893-1.webp?alt=media&token=1102239a-2592-4ad5-8ddc-ae92e8d73d58', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcardapio-la-bella-pasta-gallery-1758298262893-0-1.webp?alt=media&token=7dc1f4de-662e-4d2e-b6c0-6165a5ccbbae","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fcardapio-la-bella-pasta-gallery-1758298262893-1-2.webp?alt=media&token=00d46bed-616b-4fa1-9886-19fc556b15b5"]'::jsonb, '2025-09-19T16:11:08.511752+00:00', true, '[]'::jsonb, '16:9', '4:5', 51) ON CONFLICT DO NOTHING;
