INSERT INTO "projects" ("id", "category_id", "slug", "title", "client", "year", "services", "description", "challenge", "solution", "results", "project_url", "main_image_url", "gallery_urls", "created_at", "allow_image_download", "video_urls", "main_image_aspect_ratio", "gallery_aspect_ratio", "display_order") VALUES (36, 3, 'connect-conference-2025-site', 'Connect Conference 2025 - Site', 'Connect', 2025, '["React","Tailwind CSS","Supabase","Node.js","SEO Premium","subcategoria:criacao-de-sites"]'::jsonb, 'Desenvolvimento estratégico do site para a Connect Conference 2025, focado em alta performance e experiência imersiva, transformando visitantes em participantes.', 'O desafio era criar uma plataforma digital que refletisse a inovação da conferência e suportasse um alto volume de tráfego.', 'Implementamos um design responsivo e modular de ponta, utilizando arquitetura web escalável para garantir velocidade e estabilidade superiores.', 'O resultado foi um aumento de 45% nas interações dos participantes.', 'https://www.connectadvec.com', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-main-1768255999041-imagem_2026-01-12_190935162.webp?alt=media&token=56b036f1-6144-468a-8d69-f35b94884a41', '["https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-0-imagem_2026-01-12_191009449.webp?alt=media&token=fcac81c4-4989-4973-b342-bdf2184e36c1","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-1-imagem_2026-01-12_191021973.webp?alt=media&token=00130728-a5bf-4964-b334-f6b1645f72b4","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-2-imagem_2026-01-12_191035448.webp?alt=media&token=bd612917-8c99-483e-8edb-52bd1accda52","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-3-imagem_2026-01-12_191058977.webp?alt=media&token=f2b087a0-4530-48b4-8cac-f0592f1dd3b3","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-4-imagem_2026-01-12_191123927.webp?alt=media&token=d40cdc11-2681-4571-949c-14171fbbf945","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-5-imagem_2026-01-12_191136783.webp?alt=media&token=e5550533-5ce1-4e7a-99d1-20c4b15f05f3","https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/project-images%2Fconnect-conference-2025-site-gallery-1768255999041-6-imagem_2026-01-12_191243115.webp?alt=media&token=f28f1c70-a857-4faf-9ade-46c9a000021b"]'::jsonb, '2026-01-12T22:13:22.260589+00:00', true, '[]'::jsonb, '16:9', '16:9', 21) ON CONFLICT DO NOTHING;
