INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (19, 'Yuri Nogueira', '', 5, 'Pedi um sistema que ajudasse na gestão de uma equipe e o Rafael me entregou além do esperado, atendendo a demandas que mencionei e também a outras que eu nem imaginava que precisava. Excelente profissional, confio de olhos fechados.', NULL, '2026-02-04T02:03:43.57309+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (18, 'Thiago Ribeiro ', 'Engenheiro de telecomunicações.', 5, 'Excelente profissional,  que resolve minhas demandas até hoje.', NULL, '2026-01-31T09:24:08.690064+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (17, 'Ana Melgaço ', '', 5, 'Estou super satisfeita com a instalação de câmeras em minha residência e na minha loja, mais segurança e controle na palma da minha mão. ', NULL, '2026-01-14T01:23:46.059315+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (14, 'Lincoln Tamashiro ', 'Ágata Martins advocacia ', 5, 'Excelente profissional. Atencioso, rápido e muito experiente.', NULL, '2026-01-13T08:14:06.431772+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (15, 'Ana Beatriz ', '', 5, 'O melhor que conheço! Indico e trabalho de olhos fechados sempre. ', NULL, '2026-01-13T12:45:22.876509+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (16, 'Eduardo', 'Atelierpetshopping ', 5, 'Um ótimo profissional e recomendo de olhos fechados e de pura confiança!!', NULL, '2026-01-13T21:37:44.956+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (33, 'Christian C.', '', 5, 'Rafael foi um ótimo profissional. Apresentamos para ele as nossas ideias e ele criou as peças gráficas com muita dedicação e agilidade. Gostamos do resultado.', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444988853.webp?alt=media&token=a85d0aa0-f371-4c55-a585-c8811ebfaece', '2026-08-11T10:43:11.354575+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (32, 'Thalita C.', '', 5, 'Excelente profissional. Atendeu rapidamente minha solicitação. Fiquei muito satisfeita tanto pelo trabalho, quanto pela agilidade na entrega.', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444960241.webp?alt=media&token=291b6197-b92c-4f6b-a220-aa60d8bf54ac', '2026-08-11T10:42:43.362859+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (31, 'Sidney R.', 'Cliente 99Freelas', 5, 'Excelente, rápido, comprometido, profissional, adorei trabalhar com ele, sem contar que ele me deixava a par de todo o processo e evolução do trabalho. Super recomendo.', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444921065.webp?alt=media&token=a95d2b25-681c-469c-a473-9fb91fecf54e', '2026-08-11T10:42:04.392025+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (30, 'Leticia G.', 'Cliente 99Freelas', 5, 'Atencioso e comprometido, entragou no prazo estabelecido.', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444874644.webp?alt=media&token=2b16fbbd-99fa-4782-8401-bde5acc969bb', '2026-08-11T10:41:17.972772+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (29, 'Ribero J.', 'Cliente 99Freelas', 5, 'super recomendo, freelance entendeu de inicio o projeto e iniciou o mesmo assim que possivel, finalizando em tempo hábil e antes do prazo. Super profissional, atento e comunicativo', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444823714.webp?alt=media&token=4d6f6447-cd2f-4968-b9a0-9c57bbd2c9da', '2026-08-11T10:40:26.708158+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (28, 'Bruna C.', 'CEO', 5, 'O Rafael foi sensacional! Demos a ideia do que queríamos e ele foi além! Super fácil comunicação, fez o que pedimos, tudo foi feito de forma bastante simples e imediata, mesmo com uma dificuldades nossa de fuso horário! Recomendo 100% e se precisar de mais projetos do tipo, é com ele que vou lidar!', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444792597.webp?alt=media&token=237484dc-a41c-4474-98ac-0d474e39fbed', '2026-08-11T10:39:55.301426+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (27, 'Fernanda G.', 'Cliente 99Freelas', 5, 'Super atencioso e disposto, ótima qualidade do trabalho', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444752308.webp?alt=media&token=066ababd-f1a6-45ba-9ba3-9b93a48035d3', '2026-08-11T10:39:15.362296+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (26, 'Rodrigo R.', 'Cliente 99Freelas', 5, 'O Rafael foi direto ao ponto. Entendeu o problema, contornou as limitações e desafios da demanda para entregar o projeto. Concluiu em um tempo menor do que o estimado e tirou minhas dúvidas sobre as mudanças.', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444686472.webp?alt=media&token=e3fc0c75-342c-4e76-923f-677a1dd34b0a', '2026-08-11T10:38:09.631463+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (25, 'Vinicius G.', 'Cliente 99Freelas', 5, 'Rafael arrasou super atencioso e paciente - gratidão, muito obrigado Rafa!', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444626125.webp?alt=media&token=0fe35b39-6fcd-4998-902c-125e90c24cee', '2026-08-11T10:37:09.104643+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (24, 'Henrique', '', 5, 'otimo, fez rapido, fez certinho oque eu precisava, indico 100%', NULL, '2026-08-11T10:36:23.063019+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (23, 'Eduardo M.', 'Cliente 99Freelas', 5, 'O Rafael tem a iniciativa de investigar em detalhes quando algo está bloqueando o bom funcionamento do sistema, mesmo que isso esteja fora do escopo do projeto. Seu diagnóstico descreveu com exatidão o problema encontrado, e isso facilita que esse problema seja resolvido rapidamente. Perdi a conta de quantos projetos com o Rafael foram levados ate o fim, em todos eles sempre há persistência, rapidez e eficiência, com tudo sendo resolvido sem demoras, sem erros. Obrigado.', NULL, '2026-08-11T10:34:41.777678+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (22, 'Janaina D.', 'Cliente 99Freelas', 5, 'Rápido, excelente trabalho e proativo', 'https://firebasestorage.googleapis.com/v0/b/rafael-pita-portfolio.firebasestorage.app/o/avatars%2F1786444396856.webp?alt=media&token=6127aa49-806c-482f-b89f-3d2d01947386', '2026-08-11T10:33:20.851727+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (21, 'João H.', 'Cliente 99Freelas', 5, 'O Rafael é muito competente e rápido. Está de parabéns.', NULL, '2026-08-11T10:32:24.836073+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (20, 'Augusto S.', 'Cliente 99Freelas', 5, 'Rafael é rápido, atencioso e gentil. A entrega é ótima e o preço é muito em conta.', NULL, '2026-08-11T10:31:55.452888+00:00', true, 0, '8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "name", "role", "rating", "comment", "avatar_url", "created_at", "is_approved", "likes", "user_id") VALUES (4, 'Ricale', 'CEO', 5, 'Rafael fez as fotos da nossa loja de salgados e simplesmente ficaram incríveis!', 'https://tteamknintqgqozapxoo.supabase.co/storage/v1/object/public/avatars/8ef7ec0d-f767-45c7-bc9e-f512fd9aff0c-1758247852792.jpg', '2025-09-19T02:10:53.856503+00:00', true, 0, NULL) ON CONFLICT DO NOTHING;

